    17 #ifndef FLATBUFFERS_VERIFIER_H_
    18 #define FLATBUFFERS_VERIFIER_H_
    19
    20 #include "flatbuffers/base.h"
    21 #include "flatbuffers/util.h"
    22 #include "flatbuffers/vector.h"
    23
    24 namespace flatbuffers {
    25
    26 // Helper class to verify the integrity of a FlatBuffer
    27 class Verifier FLATBUFFERS_FINAL_CLASS {
    28  public:
    29   Verifier(const uint8_t *buf, size_t buf_len, uoffset_t _max_depth = 64,
    30            uoffset_t _max_tables = 1000000, bool _check_alignment = true)
    31       : buf_(buf),
    32         size_(buf_len),
    33         depth_(0),
    34         max_depth_(_max_depth),
    35         num_tables_(0),
    36         max_tables_(_max_tables),
    37         upper_bound_(0),
    38         check_alignment_(_check_alignment) {
    39     FLATBUFFERS_ASSERT(size_ < FLATBUFFERS_MAX_BUFFER_SIZE);
    40   }
    41
    42   // Central location where any verification failures register.
    43   bool Check(bool ok) const {
    44     // clang-format off
    45     #ifdef FLATBUFFERS_DEBUG_VERIFICATION_FAILURE
    46       FLATBUFFERS_ASSERT(ok);
    47     #endif
    48     #ifdef FLATBUFFERS_TRACK_VERIFIER_BUFFER_SIZE
    49       if (!ok)
    50         upper_bound_ = 0;
    51     #endif
    52     // clang-format on
    53     return ok;
    54   }
    55
    56   // Verify any range within the buffer.
    57   bool Verify(size_t elem, size_t elem_len) const {
    58     // clang-format off
    59     #ifdef FLATBUFFERS_TRACK_VERIFIER_BUFFER_SIZE
    60       auto upper_bound = elem + elem_len;
    61       if (upper_bound_ < upper_bound)
    62         upper_bound_ =  upper_bound;
    63     #endif
    64     // clang-format on
    65     return Check(elem_len < size_ && elem <= size_ - elem_len);
    66   }
    67
    68   template<typename T> bool VerifyAlignment(size_t elem) const {
    69     return Check((elem & (sizeof(T) - 1)) == 0 || !check_alignment_);
    70   }
    71
    72   // Verify a range indicated by sizeof(T).
    73   template<typename T> bool Verify(size_t elem) const {
    74     return VerifyAlignment<T>(elem) && Verify(elem, sizeof(T));
    75   }
    76
    77   bool VerifyFromPointer(const uint8_t *p, size_t len) {
    78     auto o = static_cast<size_t>(p - buf_);
    79     return Verify(o, len);
    80   }
    81
    82   // Verify relative to a known-good base pointer.
    83   bool Verify(const uint8_t *base, voffset_t elem_off, size_t elem_len) const {
    84     return Verify(static_cast<size_t>(base - buf_) + elem_off, elem_len);
    85   }
    86
    87   template<typename T>
    88   bool Verify(const uint8_t *base, voffset_t elem_off) const {
    89     return Verify(static_cast<size_t>(base - buf_) + elem_off, sizeof(T));
    90   }
    91
    92   // Verify a pointer (may be NULL) of a table type.
    93   template<typename T> bool VerifyTable(const T *table) {
    94     return !table || table->Verify(*this);
    95   }
    96
    97   // Verify a pointer (may be NULL) of any vector type.
    98   template<typename T> bool VerifyVector(const Vector<T> *vec) const {
    99     return !vec || VerifyVectorOrString(reinterpret_cast<const uint8_t *>(vec),
   100                                         sizeof(T));
   101   }
   102
   103   // Verify a pointer (may be NULL) of a vector to struct.
   104   template<typename T> bool VerifyVector(const Vector<const T *> *vec) const {
   105     return VerifyVector(reinterpret_cast<const Vector<T> *>(vec));
   106   }
   107
   108   // Verify a pointer (may be NULL) to string.
   109   bool VerifyString(const String *str) const {
   110     size_t end;
   111     return !str || (VerifyVectorOrString(reinterpret_cast<const uint8_t *>(str),
   112                                          1, &end) &&
   113                     Verify(end, 1) &&           // Must have terminator
   114                     Check(buf_[end] == '\0'));  // Terminating byte must be 0.
   115   }
   116
   117   // Common code between vectors and strings.
   118   bool VerifyVectorOrString(const uint8_t *vec, size_t elem_size,
   119                             size_t *end = nullptr) const {
   120     auto veco = static_cast<size_t>(vec - buf_);
   121     // Check we can read the size field.
   122     if (!Verify<uoffset_t>(veco)) return false;
   123     // Check the whole array. If this is a string, the byte past the array
   124     // must be 0.
   125     auto size = ReadScalar<uoffset_t>(vec);
   126     auto max_elems = FLATBUFFERS_MAX_BUFFER_SIZE / elem_size;
   127     if (!Check(size < max_elems))
   128       return false;  // Protect against byte_size overflowing.
   129     auto byte_size = sizeof(size) + elem_size * size;
   130     if (end) *end = veco + byte_size;
   131     return Verify(veco, byte_size);
   132   }
   133
   134   // Special case for string contents, after the above has been called.
   135   bool VerifyVectorOfStrings(const Vector<Offset<String>> *vec) const {
   136     if (vec) {
   137       for (uoffset_t i = 0; i < vec->size(); i++) {
   138         if (!VerifyString(vec->Get(i))) return false;
   139       }
   140     }
   141     return true;
   142   }
   143
   144   // Special case for table contents, after the above has been called.
   145   template<typename T> bool VerifyVectorOfTables(const Vector<Offset<T>> *vec) {
   146     if (vec) {
   147       for (uoffset_t i = 0; i < vec->size(); i++) {
   148         if (!vec->Get(i)->Verify(*this)) return false;
   149       }
   150     }
   151     return true;
   152   }
   153
   154   __supress_ubsan__("unsigned-integer-overflow") bool VerifyTableStart(
   155       const uint8_t *table) {
   156     // Check the vtable offset.
   157     auto tableo = static_cast<size_t>(table - buf_);
   158     if (!Verify<soffset_t>(tableo)) return false;
   159     // This offset may be signed, but doing the subtraction unsigned always
   160     // gives the result we want.
   161     auto vtableo = tableo - static_cast<size_t>(ReadScalar<soffset_t>(table));
   162     // Check the vtable size field, then check vtable fits in its entirety.
   163     return VerifyComplexity() && Verify<voffset_t>(vtableo) &&
   164            VerifyAlignment<voffset_t>(ReadScalar<voffset_t>(buf_ + vtableo)) &&
   165            Verify(vtableo, ReadScalar<voffset_t>(buf_ + vtableo));
   166   }
   167
   168   template<typename T>
   169   bool VerifyBufferFromStart(const char *identifier, size_t start) {
   170     if (identifier && !Check((size_ >= 2 * sizeof(flatbuffers::uoffset_t) &&
   171                               BufferHasIdentifier(buf_ + start, identifier)))) {
   172       return false;
   173     }
   174
   175     // Call T::Verify, which must be in the generated code for this type.
   176     auto o = VerifyOffset(start);
   177     return o && reinterpret_cast<const T *>(buf_ + start + o)->Verify(*this)
   178     // clang-format off
   179     #ifdef FLATBUFFERS_TRACK_VERIFIER_BUFFER_SIZE
   180            && GetComputedSize()
   181     #endif
   182         ;
   183     // clang-format on
   184   }
   185
   186   template<typename T>
   187   bool VerifyNestedFlatBuffer(const Vector<uint8_t> *buf,
   188                               const char *identifier) {
   189     if (!buf) return true;
   190     Verifier nested_verifier(buf->data(), buf->size());
   191     return nested_verifier.VerifyBuffer<T>(identifier);
   192   }
   193
   194   // Verify this whole buffer, starting with root type T.
   195   template<typename T> bool VerifyBuffer() { return VerifyBuffer<T>(nullptr); }
   196
   197   template<typename T> bool VerifyBuffer(const char *identifier) {
   198     return VerifyBufferFromStart<T>(identifier, 0);
   199   }
   200
   201   template<typename T> bool VerifySizePrefixedBuffer(const char *identifier) {
   202     return Verify<uoffset_t>(0U) &&
   203            ReadScalar<uoffset_t>(buf_) == size_ - sizeof(uoffset_t) &&
   204            VerifyBufferFromStart<T>(identifier, sizeof(uoffset_t));
   205   }
   206
   207   uoffset_t VerifyOffset(size_t start) const {
   208     if (!Verify<uoffset_t>(start)) return 0;
   209     auto o = ReadScalar<uoffset_t>(buf_ + start);
   210     // May not point to itself.
   211     if (!Check(o != 0)) return 0;
   212     // Can't wrap around / buffers are max 2GB.
   213     if (!Check(static_cast<soffset_t>(o) >= 0)) return 0;
   214     // Must be inside the buffer to create a pointer from it (pointer outside
   215     // buffer is UB).
   216     if (!Verify(start + o, 1)) return 0;
   217     return o;
   218   }
   219
   220   uoffset_t VerifyOffset(const uint8_t *base, voffset_t start) const {
   221     return VerifyOffset(static_cast<size_t>(base - buf_) + start);
   222   }
   223
   224   // Called at the start of a table to increase counters measuring data
   225   // structure depth and amount, and possibly bails out with false if
   226   // limits set by the constructor have been hit. Needs to be balanced
   227   // with EndTable().
   228   bool VerifyComplexity() {
   229     depth_++;
   230     num_tables_++;
